uint64_t s14_domestic_submit(uint64_t p,const S14DOptions *o,const S14DPlan *a){(void)o;assert(p&&apply_allowed);submits++;fixture.plan=*a;fixture.status=S14_D_APPLIED;fixture.completed=fixture.remaining=0;for(int i=0;i<a->count;i++)if(a->rows[i].selected&&a->rows[i].reason==S14_D_CHANGE){fixture.plan.rows[i].completed=1;fixture.completed++;fixture.snapshot.areas[a->rows[i].area].officer=a->rows[i].after;fixture.snapshot.areas[a->rows[i].area].project=a->rows[i].project;fixture.snapshot.cities[1].balance-=fixture.snapshot.unit_cost;}wcscpy(fixture.message,L"已完成；原生任命回读成功");return 1000+submits;}
int s14_domestic_result(uint64_t id,S14DResult *out){*out=fixture;out->id=id;out->preview=id;return 1;}
